version: '3.8'
services:
  gateway:
    image: busybox:1.36
    networks: {edge: {}}
    ports:
      - {target: 8080, published: "${APP_PORT:?required}", host_ip: 127.0.0.1, protocol: tcp}
    volumes:
      - {type: bind, source: ./gateway.conf, target: /etc/gateway/config, read_only: true}
  app:
    image: busybox:1.36
    networks: {private: {}, edge: {}}
  db:
    image: postgres:16-alpine
    networks: {private: {}}
    volumes:
      - {type: volume, source: dbdata, target: /var/lib/postgresql/data}
networks:
  private: {internal: true}
  edge:
volumes:
  dbdata:
